insert into public.ce_tool_drafts(capability_key,slug,title,summary,category,kind,risk_level,projection,lifecycle,payload,provenance) values ('research.nursing.d01','protecao-contra-violencia-e-assedio','Proteção contra violência e assédio','Central de orientação, registro privado, encaminhamento seguro, histórico do próprio usuário.','protecao','reference','high','public','candidate','{"summary":"Central de orientação, registro privado, encaminhamento seguro, histórico do próprio usuário.","disclaimer":"Protótipo candidato, sem validação clínica ou jurídica. Não registrar dados pessoais ou informações sobre pacientes. Publicação proibida antes de revisão e Kernel.","sections":[{"heading":"Necessidade identificada","body":"Proteção contra violência e assédio"},{"heading":"Solução candidata","body":"Central de orientação, registro privado, encaminhamento seguro, histórico do próprio usuário."},{"heading":"Estado de validação","body":"A pesquisa justifica investigar a demanda; conteúdo, fluxo e efetividade ainda exigem validação com usuários e revisão profissional."}],"fields":[],"referenceUrls":["https://portalcofen.gov.br/violencia-atinge-7-em-cada-10-profissionais-de-enfermagem-em-sao-paulo-aponta-sondagem/","https://pmc.ncbi.nlm.nih.gov/articles/PMC13032240/"],"safeOffline":false,"containsPatientData":false}'::jsonb,'{"source_version":"1.4.0","source_id":"D01","evidence_note":"Sondagem Coren-SP 2026 com 4.402 participantes: 72,6% relataram violência no último ano; revisão de subnotificação aponta medo de represália e complexidade dos canais.","status":"RESEARCH_CANDIDATE_NOT_APPROVED","original_risk":"alto"}'::jsonb) on conflict (capability_key) do nothing;
